void ui_networkdark_screen_clean(void)
{
    if (aidogui_ui.networkdark.root == NULL || !lv_obj_is_valid(aidogui_ui.networkdark.root)) return;
    ui_networkdark_content_ready = false;
    ui_networkdark_cleaning = true;
    lv_obj_clean(aidogui_ui.networkdark.root);
    ui_networkdark_cleaning = false;
}

